import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';

export default function JobDetails() {
  const { id } = useParams(); // Récupère l'ID depuis l'URL
  const navigate = useNavigate();
  const [job, setJob] = useState(null);

  useEffect(() => {
    fetch(`http://localhost:5000/api/jobs/${id}`)
      .then((res) => res.json())
      .then((data) => setJob(data))
      .catch((err) => console.error("Erreur:", err));
  }, [id]);

  if (!job) return <p>Chargement des détails...</p>;

  return (
    <div className="details-container" style={{ padding: '20px' }}>
      <button onClick={() => navigate(-1)}>Retour</button>
      <h1>{job.title}</h1>
      <h3 style={{ color: '#555' }}>{job.company}</h3>
      <p style={{ marginTop: '20px', lineHeight: '1.6' }}>{job.description}</p>
      
      <button 
        style={{ marginTop: '20px', padding: '10px 20px', backgroundColor: '#185fa5', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer' }}
        onClick={() => alert("Candidature envoyée !")}
      >
        Postuler à cette offre
      </button>
    </div>
  );
}
